<script>
 import {onMount,onDestroy,tick} from 'svelte';
 import {loadGoogleMaps} from '$lib/maps.js';
 let {latitude=$bindable(''),longitude=$bindable(''),maps={},disabled=false}=$props();
 let open=$state(false),busy=$state(false),failure=$state(''),view=$state('hybrid'),container=$state();
 let map=$state.raw(null),marker,api,Marker,destroyed=false;
 const point=()=>{const lat=Number(latitude),lng=Number(longitude);return latitude!==''&&latitude!==undefined&&latitude!==null&&longitude!==''&&longitude!==undefined&&longitude!==null&&Number.isFinite(lat)&&Number.isFinite(lng)&&lat>=-90&&lat<=90&&lng>=-180&&lng<=180?{lat,lng}:null;};
 function pick(position){const lat=typeof position?.lat==='function'?position.lat():position?.lat,lng=typeof position?.lng==='function'?position.lng():position?.lng;if(!Number.isFinite(lat)||!Number.isFinite(lng))return;latitude=Number(lat.toFixed(6));longitude=Number(lng.toFixed(6));}
 function dispose(){if(marker){api?.event.clearInstanceListeners(marker);marker.map=null;marker=null;}if(map)api?.event.clearInstanceListeners(map);map=null;}
 async function load(){if(busy||map||disabled)return;busy=true;failure='';try{api=await loadGoogleMaps(maps.browserKey);const library=await api.importLibrary('maps');({AdvancedMarkerElement:Marker}=await api.importLibrary('marker'));if(destroyed||!open)return;map=new library.Map(container,{center:point()||{lat:-19,lng:29.5},zoom:point()?17:6,mapId:maps.mapId||'DEMO_MAP_ID',mapTypeId:view,mapTypeControl:false,streetViewControl:false,gestureHandling:'cooperative',fullscreenControl:false});map.addListener('click',event=>{if(event.latLng)pick(event.latLng);});}catch{failure='Google Maps could not load. Check the browser key, allowed website, Maps JavaScript API and billing. You can still enter coordinates manually.';}finally{busy=false;}}
 async function toggle(){open=!open;if(open){await tick();if(maps.browserKey)load();}else dispose();}
 $effect(()=>{const current=map,position=point();if(!current)return;current.setMapTypeId(view);if(!position){if(marker){marker.map=null;api.event.clearInstanceListeners(marker);marker=null;}return;}if(!marker){marker=new Marker({map:current,position,gmpDraggable:true,title:'Selected node location. Drag to reposition, then save the form.'});marker.addListener('dragend',()=>pick(marker.position));}else marker.position=position;});
 onMount(()=>{const failed=()=>{dispose();failure='Google Maps rejected the configuration. Check website restrictions and billing; coordinate entry is still available.';};window.addEventListener('gridubuntu:maps-auth-failed',failed);return()=>window.removeEventListener('gridubuntu:maps-auth-failed',failed);});
 onDestroy(()=>{destroyed=true;dispose();});
</script>
<div class="location-picker"><button type="button" class="admin-button secondary" onclick={toggle} disabled={disabled} aria-expanded={open}>{open?'Close map picker':'Choose location on map'}</button>
{#if open}<div class="picker-content"><p>Zoom to the location, click to drop a pin, then drag it to refine the position. Your changes are saved only when you submit the form.</p><div class="picker-views" role="group" aria-label="Location picker map view">{#each [['roadmap','Street'],['terrain','Terrain'],['hybrid','Satellite + streets'],['satellite','Satellite']] as [key,label]}<button type="button" aria-pressed={view===key} class:active={view===key} onclick={()=>view=key}>{label}</button>{/each}</div><div class="picker-viewport"><div class="picker-map" bind:this={container} role="region" aria-label="Click to place or drag the node location pin"></div>{#if !map}<div class="picker-placeholder">{#if busy}Loading map…{:else if !maps.browserKey}Configure the Google Maps browser key to choose a location on the map.{:else}<button type="button" class="admin-button secondary" onclick={load}>Retry map</button>{/if}</div>{/if}</div>{#if failure}<p class="picker-error" role="alert">{failure}</p>{/if}<p class="picker-selection" role="status">{point()?`Selected: ${Number(latitude).toFixed(6)}, ${Number(longitude).toFixed(6)}`:'No pin selected. Coordinates have not been changed.'}</p><div class="picker-actions"><button type="button" class="admin-button secondary" disabled={!map} onclick={()=>{if(point()){map.setCenter(point());map.setZoom(17);}}}>Centre on pin</button><button type="button" class="admin-button secondary" onclick={()=>{latitude='';longitude='';}}>Clear location</button></div><p class="picker-terms"><a href="https://maps.google.com/help/terms_maps.html" target="_blank" rel="noreferrer">Google Maps terms</a> · <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Privacy</a>. Coordinate inputs remain available for keyboard entry.</p></div>{/if}</div>
<style>
 .location-picker{grid-column:1/-1;min-width:0}.picker-content{margin-top:14px;padding:16px;border:1px solid #d4dfca;border-radius:10px;background:#f6faf0}.picker-content p{font-size:12px!important;line-height:1.8;color:#4f6547;margin:0 0 12px!important}.picker-views,.picker-actions{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}.picker-views button{border:1px solid #cbdac0;background:#fff;padding:9px 12px;border-radius:7px;color:#35532d;font:inherit;font-size:11px;cursor:pointer}.picker-views button.active{background:#315a35;color:#fff}.picker-viewport{position:relative;border-radius:8px;overflow:hidden;margin-bottom:12px}.picker-map{height:330px;width:100%}.picker-placeholder{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:#eaf1e2;padding:24px;text-align:center;font-size:13px;color:#435e37}.picker-content .picker-error{color:#893d2b}.picker-selection{font-variant-numeric:tabular-nums}.picker-actions button{width:auto}.picker-terms a{text-decoration:underline!important;color:inherit}.picker-terms{font-size:10px!important}@media(max-width:540px){.picker-content{padding:12px}.picker-map{height:280px}}
</style>
